const app = document.getElementById('adminApp');
const toastEl = document.getElementById('toast');
const navItems = [
  ['dashboard', 'Overview'], ['products', 'Products'], ['categories', 'Categories'],
  ['orders', 'Orders'], ['coupons', 'Coupons'], ['customers', 'Customers'],
  ['staff', 'Team'], ['activity', 'Activity log']
];
let currentUser = null;
let activePage = 'dashboard';
let activePageNumber = 1;
let searchValue = '';
let productVisibility = '';
let dashboardRange = '30';
let dashboardCustom = { from: '', to: '' };
let orderFilters = { status: '', payment_status: '', from: '', to: '' };
let toastTimer;
let inactivityTimer;
const inactivityMs = 20 * 60 * 1000;
const money = (n) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(n || 0));
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function toast(message, error = false) {
  toastEl.textContent = message;
  toastEl.style.background = error ? '#8c3f3a' : '';
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.remove('show'), 2800);
}

async function api(path, options = {}) {
  const headers = { 'X-Admin-Request': '1', ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) };
  const response = await fetch(`/api/admin${path}`, { ...options, headers, credentials: 'same-origin' });
  const result = await response.json().catch(() => ({}));
  if (response.status === 401 && currentUser) { currentUser = null; showLogin('Your session expired. Sign in again.'); }
  if (!response.ok) throw new Error(result.error || 'The request could not be completed.');
  return result;
}

function showLogin(message = '') {
  clearTimeout(inactivityTimer);
  const resetToken = new URLSearchParams(location.hash.slice(1)).get('access_token');
  if (resetToken) {
    app.innerHTML = `<main class="login-wrap"><form class="login-card" id="resetForm"><h1>Set a new password</h1><p>Use at least 12 characters for your admin password.</p><div class="field"><label for="newPassword">New password</label><input id="newPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required /></div><p class="error" id="loginError">${esc(message)}</p><button class="btn primary" style="width:100%;padding:13px" type="submit">Update password</button></form></main>`;
    document.getElementById('resetForm').addEventListener('submit', async (event) => {
      event.preventDefault(); const btn = event.currentTarget.querySelector('button'); btn.disabled = true;
      try { await fetch('/api/admin/auth/password-update', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Admin-Request': '1' }, body: JSON.stringify({ accessToken: resetToken, password: document.getElementById('newPassword').value }) }).then(async r => { const j = await r.json(); if (!r.ok) throw new Error(j.error); return j; }); history.replaceState(null, '', '/admin'); showLogin('Password updated. Sign in with your new password.'); }
      catch (error) { document.getElementById('loginError').textContent = error.message; } finally { btn.disabled = false; }
    });
    return;
  }
  app.innerHTML = `<main class="login-wrap"><form class="login-card" id="loginForm"><div class="brand" style="padding:0;color:var(--ink);margin-bottom:26px">Algodon Organic<small style="color:var(--soft)">Store administration</small></div><h1 id="loginTitle">Admin sign in</h1><p id="loginDescription">Use your authorized staff account to manage the store.</p><div class="field"><label for="email">Email</label><input class="input" id="email" type="email" autocomplete="username" required maxlength="320" /></div><div class="field" id="passwordField"><label for="password">Password</label><input class="input" id="password" type="password" autocomplete="current-password" required maxlength="1024" /></div><p class="error" id="loginError">${esc(message)}</p><button class="btn primary" style="width:100%;padding:13px" type="submit" id="loginSubmit">Sign in</button><button class="btn" style="width:100%;margin-top:10px" id="forgotToggle" type="button">Forgot password?</button></form></main>`;
  let resetMode = false;
  document.getElementById('forgotToggle').addEventListener('click', () => { resetMode = !resetMode; document.getElementById('loginTitle').textContent = resetMode ? 'Reset password' : 'Admin sign in'; document.getElementById('loginDescription').textContent = resetMode ? 'We will email a secure reset link if this address belongs to an admin.' : 'Use your authorized staff account to manage the store.'; document.getElementById('passwordField').hidden = resetMode; document.getElementById('password').required = !resetMode; document.getElementById('loginSubmit').textContent = resetMode ? 'Send reset link' : 'Sign in'; document.getElementById('forgotToggle').textContent = resetMode ? 'Back to sign in' : 'Forgot password?'; document.getElementById('loginError').textContent = ''; });
  document.getElementById('loginForm').addEventListener('submit', async (event) => {
    event.preventDefault(); const btn = document.getElementById('loginSubmit'); const email = document.getElementById('email').value.trim(); btn.disabled = true;
    try {
      if (resetMode) { const response = await fetch('/api/admin/auth/password-reset', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Admin-Request': '1' }, body: JSON.stringify({ email }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); toast(result.message); return; }
      const response = await fetch('/api/admin/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Admin-Request': '1' }, credentials: 'same-origin', body: JSON.stringify({ email, password: document.getElementById('password').value }) });
      const result = await response.json(); if (!response.ok) throw new Error(result.error); currentUser = result.user; history.replaceState(null, '', '/admin'); activePage = currentUser.role==='support'?'orders':'dashboard'; beginInactivityTimer(); await render();
    } catch (error) { document.getElementById('loginError').textContent = error.message; }
    finally { btn.disabled = false; }
  });
}

function beginInactivityTimer() {
  clearTimeout(inactivityTimer);
  inactivityTimer = setTimeout(async () => { try { await api('/auth/logout', { method: 'POST' }); } catch {} currentUser = null; showLogin('You were signed out after 20 minutes without activity.'); }, inactivityMs);
}
['pointerdown', 'keydown', 'touchstart', 'mousemove'].forEach((eventName) => document.addEventListener(eventName, () => { if (currentUser) beginInactivityTimer(); }, { passive: true }));

function shell(title, content, actions = '') {
  const allowed = navItems.filter(([key]) => currentUser.role === 'support' ? ['products','orders','customers'].includes(key) : (key !== 'staff' && key !== 'activity' || currentUser.role === 'super_admin'));
  app.innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand">Algodon Organic<small>Store administration</small></div><nav class="nav">${allowed.map(([key, label]) => `<button data-page="${key}" class="${activePage === key ? 'active' : ''}">${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="user-badge">${esc(currentUser.email)}<br>${esc(currentUser.role.replace('_', ' '))}</div><button class="btn" id="logoutBtn">Sign out</button></div></aside><main class="main"><div class="topbar"><h1>${esc(title)}</h1><div class="top-actions">${actions}<button class="btn" id="themeBtn" title="Toggle light and dark mode">◐</button><span class="user-badge" style="color:var(--soft)">${esc(currentUser.role.replace('_', ' '))}</span></div></div><div class="content">${content}</div></main></div>`;
  document.querySelectorAll('[data-page]').forEach(button => button.addEventListener('click', () => { activePage = button.dataset.page; activePageNumber = 1; searchValue = ''; render(); }));
  document.getElementById('logoutBtn').addEventListener('click', async () => { try { await api('/auth/logout', { method: 'POST' }); } finally { currentUser = null; showLogin(); } });
  document.getElementById('themeBtn').addEventListener('click', () => { document.body.classList.toggle('dark'); localStorage.setItem('algodon-admin-dark', document.body.classList.contains('dark') ? '1' : '0'); });
  if (localStorage.getItem('algodon-admin-dark') === '1') document.body.classList.add('dark');
}

function moneyKpi(label, value) { return `<div class="card kpi"><div class="kpi-label">${esc(label)}</div><div class="kpi-value">${esc(value)}</div></div>`; }
function badge(value) { const s = String(value || 'Pending'); const c = ['Delivered', 'Paid', 'Confirmed'].includes(s) ? 'green' : ['Cancelled', 'Failed', 'Refunded'].includes(s) ? 'red' : ['Pending', 'Packed', 'Shipped'].includes(s) ? 'amber' : ''; return `<span class="badge ${c}">${esc(s)}</span>`; }
function chartBars(rows) { const max = Math.max(1, ...rows.map(r => Number(r.amount || 0))); return `<div class="chart">${rows.slice(-14).map((r) => `<div class="bar-column" title="${esc(r.date)} · ${esc(money(r.amount))}"><div class="bar" style="height:${Math.max(3, Number(r.amount || 0) / max * 100)}%"></div><span>${esc(r.date.slice(5))}</span></div>`).join('')}</div>`; }

async function dashboard() {
  const to = dashboardRange === 'custom' && dashboardCustom.to ? new Date(`${dashboardCustom.to}T23:59:59`) : new Date();
  let from;
  if (dashboardRange === 'custom' && dashboardCustom.from) from = new Date(`${dashboardCustom.from}T00:00:00`);
  else { from = new Date(); from.setHours(0,0,0,0); from.setDate(from.getDate() - (Number(dashboardRange) - 1)); }
  const [{ kpis, revenueByDay, ordersByStatus, lowStock, topProducts, salesByCategory }, recent] = await Promise.all([api(`/dashboard?from=${from.toISOString()}&to=${to.toISOString()}`), api('/orders?limit=5&page=1')]);
  const totalStatus = Object.values(ordersByStatus).reduce((a, b) => a + b, 0) || 1;
  shell('Overview', `<div class="toolbar"><span class="muted small">Sales performance</span><div class="toolbar-right"><select id="dashboardRange"><option value="1" ${dashboardRange==='1'?'selected':''}>Today</option><option value="7" ${dashboardRange==='7'?'selected':''}>7 days</option><option value="30" ${dashboardRange==='30'?'selected':''}>30 days</option><option value="custom" ${dashboardRange==='custom'?'selected':''}>Custom</option></select>${dashboardRange==='custom'?`<input type="date" id="dashFrom" value="${esc(dashboardCustom.from)}"><input type="date" id="dashTo" value="${esc(dashboardCustom.to)}"><button class="btn" id="applyDashDates">Apply</button>`:''}</div></div><div class="grid kpis">${moneyKpi('Revenue', money(kpis.revenue))}${moneyKpi('Orders', kpis.orders)}${moneyKpi('Average order', money(kpis.averageOrderValue))}${moneyKpi('New customers', kpis.newCustomers)}${moneyKpi('Repeat customer rate', `${(kpis.repeatCustomerRate*100).toFixed(1)}%`)}</div><div class="grid dashboard-grid"><section class="panel"><h2>Revenue over time</h2>${chartBars(revenueByDay)}</section><section class="panel"><h2>Orders by status</h2><div class="status-list">${Object.entries(ordersByStatus).map(([status, count]) => `<div><div class="status-row"><span>${esc(status)}</span><strong>${count}</strong></div><div class="status-track"><div class="status-fill" style="width:${count / totalStatus * 100}%"></div></div></div>`).join('') || '<p class="muted small">No orders in this period.</p>'}</div></section><section class="panel"><h2>Top products</h2><div class="alerts">${topProducts.map(p=>`<div class="alert-row"><span>${esc(p.name)}</span><strong>${p.quantity}</strong></div>`).join('')||'<p class="muted small">No product sales in this period.</p>'}</div></section><section class="panel"><h2>Sales by category</h2><div class="alerts">${salesByCategory.map(p=>`<div class="alert-row"><span>${esc(p.name)}</span><strong>${esc(money(p.amount))}</strong></div>`).join('')||'<p class="muted small">Category sales appear after product IDs are saved with orders.</p>'}</div></section><section class="panel"><h2>Recent orders</h2>${recent.data.length ? `<div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody>${recent.data.map(o => `<tr><td>${esc(o.id.slice(0, 8))}</td><td>${esc(o.customer.name || o.customer.email || 'Guest')}</td><td>${esc(money(o.subtotal - (o.discount || 0)))}</td><td>${badge(o.status)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted small">No recent orders.</p>'}</section><section class="panel"><h2>Low stock</h2><div class="alerts">${lowStock.length ? lowStock.map(p => `<div class="alert-row"><span>${esc(p.name)}</span>${badge(`${p.stock_count} left`)}</div>`).join('') : '<p class="muted small">No low stock alerts.</p>'}</div></section></div>`);
  document.getElementById('dashboardRange').onchange = e => { dashboardRange = e.target.value; if(dashboardRange==='custom'&&!dashboardCustom.from){const now=new Date();dashboardCustom={from:new Date(now.getTime()-29*86400000).toISOString().slice(0,10),to:now.toISOString().slice(0,10)}} render(); };
  document.getElementById('applyDashDates')?.addEventListener('click',()=>{dashboardCustom={from:document.getElementById('dashFrom').value,to:document.getElementById('dashTo').value};render()});
}

function tablePage(title, columns, rows, page, limit, total, tools = '') {
  const start = total ? (page - 1) * limit + 1 : 0; const end = Math.min(total, page * limit);
  return `<div class="toolbar"><div class="toolbar-left"><input class="search" id="tableSearch" type="search" placeholder="Search ${esc(title.toLowerCase())}" value="${esc(searchValue)}" /><button class="btn" id="searchBtn">Search</button></div><div class="toolbar-right">${tools}</div></div><div class="table-wrap"><table><thead><tr>${columns.map(c => `<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows || `<tr><td colspan="${columns.length}" class="empty">No ${esc(title.toLowerCase())} found.</td></tr>`}</tbody></table></div><div class="pagination"><span>Showing ${start}–${end} of ${total}</span><span><button class="btn" id="prevPage" ${page <= 1 ? 'disabled' : ''}>Previous</button> <button class="btn" id="nextPage" ${end >= total ? 'disabled' : ''}>Next</button></span></div>`;
}
function attachTableControls(page, limit, total) {
  document.getElementById('searchBtn')?.addEventListener('click', () => { searchValue = document.getElementById('tableSearch').value; activePageNumber = 1; render(); });
  document.getElementById('tableSearch')?.addEventListener('keydown', e => { if (e.key === 'Enter') document.getElementById('searchBtn').click(); });
  document.getElementById('prevPage')?.addEventListener('click', () => { activePageNumber = Math.max(1, page - 1); render(); });
  document.getElementById('nextPage')?.addEventListener('click', () => { if (page * limit < total) { activePageNumber = page + 1; render(); } });
}
function csvDownload(filename, rows) {
  if (!rows.length) return toast('There is no data to export.', true);
  const cols = Object.keys(rows[0]); const quote = v => `"${String(typeof v === 'object' && v !== null ? JSON.stringify(v) : v ?? '').replaceAll('"', '""')}"`;
  const csv = [cols.map(quote).join(','), ...rows.map(row => cols.map(k => quote(row[k])).join(','))].join('\r\n');
  const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); link.download = filename; link.click(); URL.revokeObjectURL(link.href);
}

async function productsView() {
  const query=new URLSearchParams({page:String(activePageNumber),limit:'25',q:searchValue});if(productVisibility)query.set('published',productVisibility);
  const p = await api(`/products?${query}`); const canEdit = ['super_admin', 'manager'].includes(currentUser.role);
  const rows = p.data.map(x => `<tr><td>${canEdit?`<input type="checkbox" data-select-product="${esc(x.id)}" aria-label="Select ${esc(x.name)}"> `:''}<div class="cell-title">${esc(x.name)}</div><div class="cell-sub">${esc(x.sku || x.slug)}</div></td><td>${esc(money(x.sale_price ?? x.price))}</td><td>${Number(x.stock_count)}</td><td>${badge(x.published ? 'Published' : 'Draft')}</td><td><div class="row-actions">${canEdit ? `<button class="btn" data-edit-product="${esc(x.id)}">Edit</button><button class="btn" data-stock-product="${esc(x.id)}">Stock</button><button class="btn" data-duplicate-product="${esc(x.id)}">Copy</button><button class="btn danger" data-delete-product="${esc(x.id)}">Delete</button>` : ''}</div></td></tr>`).join('');
  const tools = `<select id="productVisibility"><option value="" ${!productVisibility?'selected':''}>All products</option><option value="true" ${productVisibility==='true'?'selected':''}>Published</option><option value="false" ${productVisibility==='false'?'selected':''}>Drafts</option></select>${canEdit?'<button class="btn" id="bulkStock">Bulk stock</button><button class="btn" id="productImport">Import CSV</button><button class="btn" id="productExport">Export CSV</button><button class="btn primary" id="addProduct">Add product</button>':''}`;
  shell('Products', tablePage('Products', ['Product', 'Price', 'Stock', 'Visibility', 'Actions'], rows, p.page, p.limit, p.total, tools)); attachTableControls(p.page, p.limit, p.total);
  document.getElementById('productVisibility').onchange=e=>{productVisibility=e.target.value;activePageNumber=1;render()};
  document.getElementById('bulkStock')?.addEventListener('click',async()=>{const ids=[...document.querySelectorAll('[data-select-product]:checked')].map(x=>x.dataset.selectProduct);if(!ids.length)return toast('Select products first.',true);const stock=Number(prompt(`Set stock count for ${ids.length} products`));if(!Number.isInteger(stock)||stock<0)return;try{await api('/products/bulk-stock',{method:'PATCH',body:JSON.stringify({items:ids.map(id=>({id,stock_count:stock}))})});toast('Stock updated.');render()}catch(e){toast(e.message,true)}});
  document.getElementById('addProduct')?.addEventListener('click', () => productModal());
  document.getElementById('productExport')?.addEventListener('click', async () => { const all = await api('/products/export'); csvDownload('algodon-products.csv', all.data); });
  document.getElementById('productImport')?.addEventListener('click', importProducts);
  document.querySelectorAll('[data-edit-product]').forEach(b => b.onclick = async () => { const all = await api('/products?page=1&limit=100'); productModal(all.data.find(x => x.id === b.dataset.editProduct)); });
  document.querySelectorAll('[data-delete-product]').forEach(b => b.onclick = async () => { if (!confirm('Delete this product? This cannot be undone.')) return; try { await api(`/products/${b.dataset.deleteProduct}`, { method: 'DELETE' }); toast('Product deleted.'); render(); } catch(e) { toast(e.message, true); } });
  document.querySelectorAll('[data-duplicate-product]').forEach(b => b.onclick = async () => { try { await api(`/products/${b.dataset.duplicateProduct}/duplicate`, { method: 'POST', body: '{}' }); toast('Draft copy created.'); render(); } catch(e) { toast(e.message, true); } });
  document.querySelectorAll('[data-stock-product]').forEach(b => b.onclick = async () => { const stock = Number(prompt('New stock count')); if (!Number.isInteger(stock) || stock < 0) return; try { await api('/products/bulk-stock', { method: 'PATCH', body: JSON.stringify({ items: [{ id: b.dataset.stockProduct, stock_count: stock }] }) }); toast('Stock updated.'); render(); } catch(e) { toast(e.message, true); } });
}

async function productModal(product = {}) {
  const categories = (await api('/categories')).data;
  modal(`<h2>${product.id ? 'Edit product' : 'Add product'}</h2><form id="editForm"><div class="form-grid">
    ${field('name', 'Name', product.name, true)}${field('slug', 'Slug', product.slug, true)}${field('sku', 'SKU', product.sku, false)}${field('brand', 'Brand', product.brand || 'Algodon Organic')}
    ${field('price', 'Price (₹)', product.price, true, 'number')}${field('sale_price', 'Sale price (₹)', product.sale_price, false, 'number')}${field('stock_count', 'Stock count', product.stock_count ?? 0, true, 'number')}${field('low_stock_threshold', 'Low stock alert at', product.low_stock_threshold ?? 5, true, 'number')}
    <div class="field"><label>Category</label><select name="category_id"><option value="">No category</option>${categories.map(c => `<option value="${esc(c.id)}" ${product.category_id === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></div>
    ${field('tags', 'Tags · comma separated', (product.tags || []).join(', '))}
    <div class="field full"><label>Description</label><textarea name="description" rows="4" maxlength="10000">${esc(product.description)}</textarea></div>
    <div class="field full"><label>Variants · JSON (example: [{"size":"M","stock":5}])</label><textarea name="variants" rows="3">${esc(JSON.stringify(product.variants || [], null, 2))}</textarea></div>
    ${field('seo_title', 'SEO title', product.seo_title)}<div class="field"><label>Meta description</label><input name="meta_description" maxlength="320" value="${esc(product.meta_description)}" /></div>
    <div class="field full"><label>Product images</label><div class="drop-zone" id="imageDrop">Drop images here or choose files<input name="image_files" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple /></div><div class="thumbs" id="imageThumbs">${(product.images || []).map((url,i) => `<div class="thumb"><img src="${esc(url)}" alt=""><button type="button" data-move-image="${i}">↑</button><button type="button" data-remove-image="${i}">×</button></div>`).join('')}</div><p class="small muted">Images compress to WebP in your browser before upload. Move an image first to set the main image.</p></div>
    ${field('images', '', JSON.stringify(product.images || []), false, 'hidden')}
    <label class="checkline full"><input type="checkbox" name="published" ${product.published ? 'checked' : ''}> Published on storefront</label><label class="checkline full"><input type="checkbox" name="out_of_stock_hidden" ${product.out_of_stock_hidden ? 'checked' : ''}> Hide when out of stock</label>
    </div><div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancel</button><button class="btn primary">Save product</button></div></form>`);
  const form = document.getElementById('editForm'); let images = [...(product.images || [])]; const deletedImages=[];
  const dropZone=document.getElementById('imageDrop');dropZone.ondragover=e=>{e.preventDefault();dropZone.classList.add('dragging')};dropZone.ondragleave=()=>dropZone.classList.remove('dragging');dropZone.ondrop=e=>{e.preventDefault();dropZone.classList.remove('dragging');const transfer=new DataTransfer();[...form.elements.image_files.files,...e.dataTransfer.files].forEach(f=>transfer.items.add(f));form.elements.image_files.files=transfer.files};
  function drawImages(){document.getElementById('imageThumbs').innerHTML=images.map((url,i)=>`<div class="thumb"><img src="${esc(url)}" alt=""><button type="button" data-move-image="${i}" ${i===0?'disabled':''}>↑</button><button type="button" data-remove-image="${i}">×</button></div>`).join('');form.elements.images.value=JSON.stringify(images);form.querySelectorAll('[data-move-image]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.moveImage);if(i>0){[images[i-1],images[i]]=[images[i],images[i-1]];drawImages()}});form.querySelectorAll('[data-remove-image]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.removeImage);const url=images[i];if(url.includes('/storage/v1/object/public/admin-product-images/'))deletedImages.push(url);images.splice(i,1);drawImages()})}
  drawImages();
  form.elements.name.addEventListener('input', () => { if (!product.id) form.elements.slug.value = form.elements.name.value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); });
  form.addEventListener('submit', async event => { event.preventDefault(); const btn = form.querySelector('button.primary'); btn.disabled = true;
    try {
      const files = [...form.elements.image_files.files]; if (files.length) { const body = new FormData(); for (const file of files) body.append('images', await compressImage(file)); const uploaded = await api('/images', { method: 'POST', body }); images = images.concat(uploaded.data.map(x => x.url)); }
      const variants = JSON.parse(form.elements.variants.value || '[]');
      const stockCount = variants.length ? variants.reduce((sum, variant) => sum + Number(variant.stock || 0), 0) : Number(form.elements.stock_count.value);
      const payload = { name: form.elements.name.value.trim(), slug: form.elements.slug.value.trim(), sku: form.elements.sku.value.trim() || null, brand: form.elements.brand.value, price: Number(form.elements.price.value), sale_price: form.elements.sale_price.value ? Number(form.elements.sale_price.value) : null, stock_count: stockCount, low_stock_threshold: Number(form.elements.low_stock_threshold.value), category_id: form.elements.category_id.value || null, tags: form.elements.tags.value.split(',').map(x=>x.trim()).filter(Boolean), description: form.elements.description.value, variants, seo_title: form.elements.seo_title.value, meta_description: form.elements.meta_description.value, images, published: form.elements.published.checked, out_of_stock_hidden: form.elements.out_of_stock_hidden.checked };
      await api(product.id ? `/products/${product.id}` : '/products', { method: product.id ? 'PATCH' : 'POST', body: JSON.stringify(payload) });
      for(const url of deletedImages) await api('/images',{method:'DELETE',body:JSON.stringify({url})});
      closeModal(); toast('Product saved.'); render();
    } catch(error) { toast(error.message, true); } finally { btn.disabled = false; }
  });
}
function field(name,label,value='',required=false,type='text') { return `<div class="field"><label for="f-${esc(name)}">${esc(label || name)}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} /></div>`; }
async function compressImage(file) {
  if (!file.type.startsWith('image/')) throw new Error('Choose an image file.');
  const image = await createImageBitmap(file); const scale = Math.min(1, 2200 / Math.max(image.width, image.height));
  const canvas = document.createElement('canvas'); canvas.width = Math.round(image.width * scale); canvas.height = Math.round(image.height * scale); canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height);
  const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/webp', .84)); if (!blob) throw new Error('Image compression failed.'); return new File([blob], `${file.name.replace(/\.[^.]+$/, '')}.webp`, { type: 'image/webp' });
}
function modal(content) { const wrap = document.createElement('div'); wrap.className = 'modal-backdrop'; wrap.id = 'activeModal'; wrap.innerHTML = `<section class="modal">${content}</section>`; document.body.appendChild(wrap); wrap.addEventListener('click', e => { if (e.target === wrap || e.target.closest('[data-close-modal]')) closeModal(); }); }
function closeModal() { document.getElementById('activeModal')?.remove(); }

