async function orderModal(id){const {data:o}=await api(`/orders/${id}`);modal(`<h2>Order · ${esc(o.id.slice(0,8))}</h2><div class="small muted">Placed ${new Date(o.created_at).toLocaleString('en-IN')} · ${esc(o.customer.email||'')}</div><p class="small">${esc(o.customer.name||'')} · ${esc(o.customer.phone||'')}<br>${esc([o.customer.address1,o.customer.address2,o.customer.city,o.customer.state,o.customer.pin].filter(Boolean).join(', '))}<br>Payment: ${esc(o.payment_method||'Not recorded')} · ${esc(o.payment_status||'Pending')}</p><h3>Items</h3><div class="table-wrap"><table><thead><tr><th>Product</th><th>Size</th><th>Qty</th><th>Unit price</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.size)}</td><td>${esc(i.qty)}</td><td>${esc(money(i.price))}</td></tr>`).join('')}</tbody></table></div><p><b>Subtotal:</b> ${esc(money(o.subtotal))} · <b>Discount:</b> ${esc(money(o.discount))} · <b>Total:</b> ${esc(money(o.subtotal-o.discount))}</p><form id="editForm"><div class="form-grid"><div class="field"><label>Order status</label><select name="status">${['Pending','Confirmed','Packed','Shipped','Delivered','Cancelled','Returned','Refunded'].filter(s=>currentUser.role!=='support'||s!=='Refunded'||o.status==='Refunded').map(s=>`<option ${o.status===s?'selected':''} ${currentUser.role==='support'&&s==='Refunded'?'disabled':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Payment status</label><select name="payment_status" ${currentUser.role==='support'?'disabled':''}>${['Pending','Paid','Failed','Partially Refunded','Refunded'].map(s=>`<option ${o.payment_status===s?'selected':''}>${s}</option>`).join('')}</select></div>${field('courier_name','Courier',o.courier_name)}${field('tracking_number','Tracking number',o.tracking_number)}<div class="field full"><label>Internal notes</label><textarea name="internal_notes" rows="4">${esc(o.internal_notes)}</textarea></div></div><p class="small muted">Refund status is recorded here. Connect a payment gateway to issue money refunds.</p><div class="modal-actions"><button type="button" class="btn" data-print-order="invoice">Print invoice</button><button type="button" class="btn" data-print-order="packing">Packing slip</button><button type="button" class="btn" data-close-modal>Close</button><button class="btn primary">Save updates</button></div></form>`);document.querySelector('[data-print-order="invoice"]').onclick=()=>printOrder(o,false);document.querySelector('[data-print-order="packing"]').onclick=()=>printOrder(o,true);document.getElementById('editForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const update={status:f.elements.status.value,courier_name:f.elements.courier_name.value,tracking_number:f.elements.tracking_number.value,internal_notes:f.elements.internal_notes.value};if(currentUser.role!=='support')update.payment_status=f.elements.payment_status.value;await api(`/orders/${id}`,{method:'PATCH',body:JSON.stringify(update)});closeModal();toast('Order updated.');render()}catch(err){toast(err.message,true)}};}
function printOrder(o,packing){const w=window.open('','_blank','width=800,height=900');if(!w)return toast('Allow pop-ups to print this order.',true);const items=o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.size)}</td><td>${esc(i.qty)}</td><td>${esc(money(i.price))}</td></tr>`).join('');const c=o.customer||{};w.document.write(`<!doctype html><title>${packing?'Packing slip':'Invoice'} ${esc(o.id.slice(0,8))}</title><style>body{font:14px Arial;padding:40px;color:#302b25}h1{font:28px Georgia}table{width:100%;border-collapse:collapse;margin-top:24px}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd}.total{text-align:right;margin-top:24px}</style><h1>Algodon Organic</h1><h2>${packing?'Packing slip':'Order invoice'} · ${esc(o.id.slice(0,8))}</h2><p>${esc(c.name)} · ${esc(c.email)} · ${esc(c.phone)}</p><p>${esc([c.address1,c.address2,c.city,c.state,c.pin].filter(Boolean).join(', '))}</p><table><tr><th>Product</th><th>Size</th><th>Qty</th><th>Price</th></tr>${items}</table>${packing?'':`<p class="total">Subtotal ${esc(money(o.subtotal))}<br>Discount ${esc(money(o.discount))}<br><b>Total ${esc(money(o.subtotal-o.discount))}</b></p>`}<script>window.print()</script>`);w.document.close();}

