function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted&&ch==='"'&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=ch}if(cell||row.length){row.push(cell);rows.push(row)}if(!rows.length)return[];const keys=rows.shift();return rows.map(values=>Object.fromEntries(keys.map((k,i)=>[k,values[i]||''])))}
function importProducts(){const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{try{const rows=parseCsv(await input.files[0].text()).map(r=>({...r,price:Number(r.price),sale_price:r.sale_price?Number(r.sale_price):null,stock_count:Number(r.stock_count||0),low_stock_threshold:Number(r.low_stock_threshold||5),published:r.published==='true',out_of_stock_hidden:r.out_of_stock_hidden==='true',tags:JSON.parse(r.tags||'[]'),variants:JSON.parse(r.variants||'[]'),images:JSON.parse(r.images||'[]'),category_id:r.category_id||null}));const result=await api('/products/import',{method:'POST',body:JSON.stringify({products:rows})});toast(`${result.imported} products imported.`);render()}catch(e){toast(e.message,true)}};input.click()}

async function render(){if(!currentUser)return showLogin();try{if(activePage==='dashboard')return await dashboard();if(activePage==='products')return await productsView();if(activePage==='categories')return await categoriesView();if(activePage==='orders')return await ordersView();if(activePage==='coupons')return await couponsView();if(activePage==='customers')return await customersView();if(activePage==='staff')return await staffView();if(activePage==='activity')return await activityView();}catch(error){if(!currentUser)return showLogin();shell('Something went wrong',`<div class="panel"><p class="error">${esc(error.message)}</p><button class="btn" id="retry">Try again</button></div>`);document.getElementById('retry').onclick=render}}

async function start(){try{const {user}=await api('/me');currentUser=user;if(user.role==='support'&&!['orders','products','customers'].includes(activePage))activePage='orders';beginInactivityTimer();await render()}catch{showLogin()}}
start();
